{"packet_id":"D005-01","doc_id":"D005","jurisdiction":"CA","category":"application_screening_fees","lifecycle":"enacted","title":"California tenant screening fee cap and disclosure rights (2026)","requirement":"A landlord may charge no more than $68.96 for tenant screening in 2026, must give the applicant a receipt, an itemized list of costs and a copy of any credit report within 7 days, refund the unused portion, and return fees to applicants not selected.","key_value":"$68.96 maximum screening fee (2026)","coverage_conditions":"Landlords charging prospective tenants a screening fee to obtain information such as a consumer credit report for a residential rental unit; no fee may be charged when no unit is actually available.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":null},"exemptions":null,"penalty":null,"effective_date":"2026","citation":"Cal. Civ. Code § 1950.6","quoted_span":"The maximum tenant screening fee for 2026 is\n$68.96","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D005-01","doc_id":"D005","jurisdiction":"CA","category":"screening_restrictions","lifecycle":"enacted","title":"California reusable tenant screening report requirement","requirement":"If an applicant provides a reusable tenant screening report, the landlord must use it for screening.","key_value":null,"coverage_conditions":"Landlords screening prospective tenants for residential rental units in California.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":null},"exemptions":null,"penalty":null,"effective_date":null,"citation":"Cal. Civ. Code § 1950.6","quoted_span":"If the tenant provides a reusable screening report, the landlord must use it.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D005-01","doc_id":"D005","jurisdiction":"Berkeley, CA","category":"application_screening_fees","lifecycle":"enacted","title":"Berkeley tenant screening fee rights disclosure and non-refundable application fee ban","requirement":"A Berkeley owner who charges a screening fee must first give the applicant a clear tenant screening fee rights statement and the statutory fee cap. An owner may not charge an existing tenant a non-refundable fee to renew a tenancy or change roommates.","key_value":null,"coverage_conditions":"All residential rental agreements in Berkeley, regardless of contrary lease language; applies to owners and their agents who charge screening or application fees.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"All residential rental agreements in Berkeley"},"exemptions":null,"penalty":"Any provision of an existing rental agreement or lease that violates the chapter is unenforceable.","effective_date":null,"citation":"Berkeley Mun. Code ch. 13.78","quoted_span":"An owner of residential rental property (or the owner’s agent) cannot charge a non-refundable fee to any existing tenant for the purpose of renewing a tenancy, in whole or in part, including any fee associated with the departure of a roommate or to request to add or replace a roommate in a pre-existing household.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
